import { step } from "../world/movement.js";
import { bounce } from "../world/bounds.js";

const BELL = "silver";
const TENTACLE = "blue";

export function spawn(world) {
  return {
    x: 20 + Math.random() * (world.width - 40),
    y: 60 + Math.random() * 100,
    vx: 0,
    vy: 0.4,
    phase: Math.random() * Math.PI * 2,
    drift: (Math.random() - 0.5) * 0.2,
  };
}

export function update(jelly, world) {
  jelly.phase += 0.05;
  // Gentle pulse pushes it up, drift keeps it slowly sideways.
  jelly.vy = -0.3 + 0.5 * Math.cos(jelly.phase);
  jelly.vx = jelly.drift;
  step(jelly);
  bounce(jelly);
}

export function draw(jelly, pen) {
  pen.stroke(TENTACLE, 2);
  for (let i = -2; i <= 2; i += 1) {
    const sway = Math.sin(jelly.phase + i) * 4;
    pen.line(i * 6, 8, i * 6 + sway, 26);
  }
  pen.fill(BELL);
  pen.ellipse(0, 4, 14, 8);
  pen.arc(0, 4, 14, Math.PI, 2 * Math.PI);
}

