import { step, glide } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const BODY = "#ff7f50";
const SNOUT = "gold";
const FIN = "pink";
const EYE = "black";

export function spawn() {
  return {
    vx: (Math.random() < 0.5 ? -1 : 1) * 0.4,
    vy: 0,
    phase: Math.random() * 2 * Math.PI,
    flip: false,
  };
}

export function update(seahorse, world) {
  seahorse.phase += 0.05;
  seahorse.vy += Math.sin(seahorse.phase) * 0.1;
  seahorse.vx += (Math.random() - 0.5) * 0.02;
  glide(seahorse, 0.95);
  seahorse.flip = seahorse.vx < 0;
  step(seahorse);
  keepInside(seahorse);
}

export function draw(seahorse, pen) {
  if (seahorse.flip) pen.flip();
  pen.fill(BODY);
  pen.ellipse(0, -14, 9, 13);
  pen.stroke(SNOUT);
  pen.line(6, -20, 15, -17);
  pen.fill(BODY);
  pen.ellipse(0, 4, 6, 9);
  pen.fill(FIN);
  pen.poly([-4, 10, -12, 14, -5, 16]);
  pen.fill(EYE);
  pen.circle(4, -18, 1.6);
}

