import { step } from "../world/movement.js";
import { keepInside, FLOOR_Y } from "../world/bounds.js";

const BODY = "#ff7a5c";
const ARMS = "#ff9a7a";
const DOTS = "#ffd9c9";

const TURN_SPEED = 0.002; // radians per tick, a slow spin

export function spawn() {
  return {
    vx: 0,
    vy: 0,
    x: 60 + Math.random() * 480,
    y: FLOOR_Y,
    angle: Math.random() * Math.PI * 2,
    spin: 1,
  };
}

export function update(star, world) {
  star.angle += TURN_SPEED * star.spin;
  step(star);
  keepInside(star);
}

export function draw(star, pen) {
  pen.turn(star.angle);
  // Five arms
  pen.fill(ARMS);
  for (let i = 0; i < 5; i++) {
    pen.turn((Math.PI * 2) / 5);
    pen.poly([0, 0, -7, -14, 0, -30, 7, -14]);
  }
  // Body disc
  pen.fill(BODY);
  pen.circle(0, 0, 11);
  // Little dots along each arm
  pen.fill(DOTS);
  for (let i = 0; i < 5; i++) {
    pen.turn((Math.PI * 2) / 5);
    pen.circle(0, -19, 2);
  }
}

