import { FLOOR_Y, POOL_WIDTH } from "../world/bounds.js";

const BODY = "darkred";
const SPINE = "black";

export function spawn() {
  return {
    vx: 0,
    vy: 0,
    x: Math.random() * POOL_WIDTH,
    y: FLOOR_Y - 4,
    sway: Math.random() * Math.PI * 2,
    speed: 0.05 + Math.random() * 0.05,
    spread: 14 + Math.random() * 6,
  };
}

export function update(urchin, world) {
  urchin.sway += urchin.speed;
}

export function draw(urchin, pen) {
  const s = Math.sin(urchin.sway);
  // spines radiating out, tips waving with the sway
  pen.stroke(SPINE);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const wave = s * 0.15;
    const len = urchin.spread;
    const tipX = Math.cos(a + wave) * len;
    const tipY = Math.sin(a + wave) * len;
    pen.line(Math.cos(a) * 5, Math.sin(a) * 5, tipX, tipY);
  }
  pen.fill(BODY);
  pen.circle(0, 0, 7);
}

