import { step, steer, glide } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const TOP = "blue";
const UNDERSIDE = "silver";
const WING_TIP = "teal";
const EYE = "black";

export function spawn() {
  // Each ray circles slowly around its own unseen centre.
  return {
    vx: 0.5,
    vy: 0,
    energy: 0,
    cx: 0,
    cy: 0,
    angle: Math.random() * Math.PI * 2,
  };
}

export function update(ray, world) {
  if (ray.cx === 0 && ray.cy === 0) {
    // Pick a centre once, offset from the ray's start so the circle is wide.
    ray.cx = ray.x + (Math.random() < 0.5 ? -180 : 180);
    ray.cy = ray.y + (Math.random() < 0.5 ? -120 : 120);
  }
  // Follow a point a little ahead on the circle: this produces gliding loops.
  const radius = Math.max(1, Math.hypot(ray.x - ray.cx, ray.y - ray.cy));
  ray.angle += 0.012; // slow, wide sweep
  const aheadX = ray.cx + Math.cos(ray.angle) * radius;
  const aheadY = ray.cy + Math.sin(ray.angle) * radius;
  steer(ray, aheadX, aheadY, 0.04);
  glide(ray, 0.995);
  step(ray);
  keepInside(ray);
}

export function draw(ray, pen) {
  if (ray.vx < 0) pen.flip();
  const sway = Math.sin(ray.age * 0.05) * 2;
  // Underside shadow
  pen.fill(UNDERSIDE);
  pen.poly([-8, -4, 0, 6, 8, -4]);
  // Wide wings
  pen.fill(TOP);
  pen.poly([-6, 0, -34, -16 + sway, -40, -4, -30, 4, -12, 2]);
  pen.poly([6, 0, 34, -16 + sway, 40, -4, 30, 4, 12, 2]);
  // Body, wingtip lines and tail
  pen.ellipse(0, 0, 14, 9);
  pen.stroke(WING_TIP, 1);
  pen.line(-12, 1, -40, -5 + sway);
  pen.line(12, 1, 40, -5 + sway);
  pen.line(0, 7, 0, 34); // tail
  pen.fill(EYE);
  pen.circle(6, -4, 1.5);
}

