import { isNight } from "../world/time.js";
import { step, wander, glide } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const DAY_BODY = "#ff6fae";
const DAY_ARM = "#ff9ec4";
const NIGHT_BODY = "#3b2a4f";
const NIGHT_ARM = "#241a35";
const EYE = "white";
const PUPIL = "black";

export const count = 1;

export function spawn() {
  return {
    x: 400,
    y: 400,
    vx: 0.4,
    vy: 0,
    pulse: Math.random() * 10,
    dir: Math.random() < 0.5 ? -1 : 1,
  };
}

export function update(octopus, world) {
  octopus.pulse += 0.1;
  octopus.dir += (Math.random() - 0.5) * 0.04;
  wander(octopus, 0.05);
  glide(octopus, 0.96);
  step(octopus);
  keepInside(octopus);
}

export function draw(octopus, pen, world) {
  const night = isNight(world);
  const body = night ? NIGHT_BODY : DAY_BODY;
  const arm = night ? NIGHT_ARM : DAY_ARM;
  const wave = Math.sin(octopus.pulse) * 4;
  if (octopus.vx < 0) pen.flip();
  // eight arms
  for (let i = 0; i < 8; i++) {
    const spread = (i - 3.5) * 7;
    const sway = Math.sin(octopus.pulse + i * 0.7) * 5;
    pen.fill(arm);
    pen.ellipse(spread, 12 + Math.abs(spread) * 0.3 + sway * 0.4, 3, 14 + (i % 2) * 4, spread * 0.02);
  }
  // mantle
  pen.fill(body);
  pen.ellipse(0, -2, 18, 14 + wave * 0.4);
  // eyes
  pen.fill(EYE);
  pen.circle(-7, -4, 3);
  pen.circle(7, -4, 3);
  pen.fill(PUPIL);
  pen.circle(-7, -4, 1.2);
  pen.circle(7, -4, 1.2);
}

