import { ENERGY_MAX, isHungry } from "../world/energy.js";
import { nearestFood } from "../world/food.js";
import { step, steer, glide, wander, distance } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const BODY = "#3a6fd8";
const FIN = "#7fb2ff";
const STRIPE = "#dfe9ff";

// How close a fish wants to stay to the school's centre.
const STAY_CLOSE = 40;
// How far apart fish never want to be.
const TOO_CLOSE = 16;

export const count = 8;

export function spawn() {
  return {
    x: Math.random() * 200 - 100,
    y: Math.random() * 100 - 50,
    vx: 1 + Math.random(),
    vy: (Math.random() - 0.5) * 0.5,
    energy: ENERGY_MAX,
  };
}

export function update(fish, world) {
  // Swim with the school: head for the average position and direction of
  // every other blue fish, and avoid crowding them.
  const school = world.creatures.filter((c) => c.kind === fish.kind && c !== fish);
  if (school.length > 0) {
    let cx = 0;
    let cy = 0;
    let vx = 0;
    let vy = 0;
    for (const other of school) {
      cx += other.x;
      cy += other.y;
      vx += other.vx;
      vy += other.vy;
    }
    const n = school.length;
    cx /= n;
    cy /= n;
    if (distance(fish, { x: cx, y: cy }) > STAY_CLOSE) steer(fish, cx, cy, 0.15);
    vx /= n;
    vy /= n;
    fish.vx += (vx - fish.vx) * 0.05;
    fish.vy += (vy - fish.vy) * 0.05;
    for (const other of school) {
      if (distance(fish, other) < TOO_CLOSE) {
        fish.vx += (fish.x - other.x) * 0.05;
        fish.vy += (fish.y - other.y) * 0.05;
      }
    }
  }

  // Hungry fish break away from the school toward the nearest food.
  const food = isHungry(fish) ? nearestFood(fish, world) : null;
  if (food) steer(fish, food.x, food.y, 0.2);
  else wander(fish, 0.03);

  glide(fish, 0.97);
  step(fish);
  keepInside(fish);
}

export function draw(fish, pen) {
  if (fish.vx < 0) pen.flip();
  pen.fill(FIN);
  pen.poly([-10, 0, -18, -8, -18, 8]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 11, 6);
  pen.fill(STRIPE);
  pen.rect(-3, -5, 3, 10);
  pen.fill("black");
  pen.circle(6, -2, 1.5);
}

