import { step, wander, glide, distance } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

const BODY = "sandybrown";
const BELLY = "lightyellow";
const SPINE = "black";
const FIN = "peachpuff";

// How near another creature must be, in pool units, before the fish puffs up.
const PUFF_DISTANCE = 40;

export const count = 2;

export function spawn() {
  return { vx: 0.5, vy: 0, puff: 0 };
}

export function update(puffer, world) {
  let nearest = null;
  for (const other of world.creatures) {
    if (other === puffer) continue;
    const far = distance(puffer, other);
    if (!nearest || far < nearest) nearest = far;
  }
  const scared = nearest !== null && nearest < PUFF_DISTANCE;
  // The puff grows while someone is close and shrinks slowly once they leave.
  puffer.puff += scared ? 0.25 : -0.02;
  if (puffer.puff < 0) puffer.puff = 0;
  if (puffer.puff > 1) puffer.puff = 1;

  if (scared) {
    wander(puffer, 0.15);
    glide(puffer, 0.95);
  } else {
    wander(puffer, 0.08);
    glide(puffer, 0.98);
  }
  step(puffer);
  wrap(puffer);
}

export function draw(puffer, pen) {
  const size = 1 + puffer.puff * 1.2;
  if (puffer.vx < 0) pen.flip();
  pen.fill(FIN);
  pen.poly([-12 * size, 0, -22 * size, -9 * size, -22 * size, 9 * size]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 16 * size, 12 * size);
  pen.fill(BELLY);
  pen.ellipse(2 * size, 4 * size, 9 * size, 6 * size);
  // Spines come out as it puffs up.
  if (puffer.puff > 0.15) {
    pen.fill(SPINE);
    const reach = 1 + puffer.puff * 0.9;
    for (const [sx, sy] of [
      [0, -12], [-8, -9], [8, -9], [-14, 0], [14, 0], [8, 9], [-8, 9], [0, 12],
    ]) {
      pen.line(sx * size, sy * size, sx * 1.35 * reach, sy * 1.35 * reach);
    }
  }
  pen.fill("black");
  pen.circle(9 * size, -3, 2);
}

