import { ENERGY_MAX, isHungry } from "../world/energy.js";
import { nearestFood } from "../world/food.js";
import { FLOOR_Y, bounce } from "../world/bounds.js";
import { distance, step, steer, glide } from "../world/movement.js";

const BODY = "silver";
const STRIPE = "royalblue";
const FIN = "skyblue";

// A cleaner fish never swims alone: one per turtle.
export const count = 2;

// How close it likes to stay to its turtle, in pool units.
const TAIL_GAP = 34;

export function spawn() {
  return { vx: 1, energy: ENERGY_MAX };
}

function nearestTurtle(fish, world) {
  let best = null;
  let bestFar = Infinity;
  for (const other of world.creatures) {
    if (other.kind !== "turtle") continue;
    const far = distance(fish, other);
    if (far < bestFar) {
      best = other;
      bestFar = far;
    }
  }
  return best;
}

export function update(fish, world) {
  const turtle = nearestTurtle(fish, world);
  if (turtle) {
    const behind = fish.x < turtle.x ? -1 : 1;
    steer(fish, turtle.x - behind * TAIL_GAP, turtle.y - 18, 0.15);
    if (distance(fish, turtle) < 18) glide(fish, 0.8);
  } else {
    steer(fish, fish.x + (fish.vx < 0 ? -100 : 100), fish.y, 0.05);
  }
  if (isHungry(fish) && !turtle) {
    const food = nearestFood(fish, world);
    if (food) steer(fish, food.x, food.y, 0.2);
  }
  glide(fish, 0.97);
  step(fish);
  bounce(fish);
  fish.y = Math.min(FLOOR_Y, fish.y);
}

export function draw(fish, pen) {
  if (fish.vx < 0) pen.flip();
  pen.fill(FIN);
  pen.poly([-16, 0, -26, -9, -26, 9]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 17, 8);
  pen.fill(STRIPE);
  pen.line(-8, -6, -4, 6);
  pen.line(-2, -7, 2, 6);
  pen.fill("black");
  pen.circle(9, -2, 1.5);
}
